package com.smartinternship.model; import jakarta.persistence.*; import jakarta.validation.constraints.NotBlank; @Entity @Table(name="internship_offers") public class InternshipOffer { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank private String title; @NotBlank private String company; private String domain; @Column(length=1000) private String requiredSkills; private String location; @Column(length=2000) private String description; public InternshipOffer(){} public InternshipOffer(String t,String c,String d,String s,String l,String x){title=t;company=c;domain=d;requiredSkills=s;location=l;description=x;} public Long getId(){return id;} public String getTitle(){return title;} public String getCompany(){return company;} public String getDomain(){return domain;} public String getRequiredSkills(){return requiredSkills;} public String getLocation(){return location;} public String getDescription(){return description;} public void setId(Long x){id=x;} public void setTitle(String x){title=x;} public void setCompany(String x){company=x;} public void setDomain(String x){domain=x;} public void setRequiredSkills(String x){requiredSkills=x;} public void setLocation(String x){location=x;} public void setDescription(String x){description=x;} }